import sys; sys.path.insert(0,'/tmp/an')
from load import *
import random
from collections import Counter,defaultdict
random.seed(1)
C=[r for r in rows if r['c']]
print('reopen',Counter((r['severity'],r['service_group']) for r in C if r['re']))
print('handoffs sev1 assist',[r['ho'] for r in C if r['workflow']=='assist' and r['severity']=='sev1'])
print('sev1 assist missing ids',[(r['incident_id'],r['opened_at']) for r in rows if r['c'] is None and r['severity']=='sev1'])
# severity mix by group/channel
for k in ['service_group','intake_channel']:
    for v in set(r[k] for r in rows):
        print(k,v,{w:[sum(1 for r in rows if r['workflow']==w and r[k]==v and r['severity']==s) for s in('sev1','sev2','sev3')] for w in('manual','assist')})
# standardized contrast with bootstrap (strata sev), weights = pooled open mix
sevs=['sev1','sev2','sev3']
W={s:sum(1 for r in rows if r['severity']==s)/420 for s in sevs}
def stdz(data,key,w=W):
    out=0
    for s in sevs:
        a=[r[key] for r in data if r['workflow']=='assist' and r['severity']==s]; m=[r[key] for r in data if r['workflow']=='manual' and r['severity']==s]
        out+=w[s]*(st.mean(a)-st.mean(m))
    return out
def boot(key,w=W,B=2000):
    xs=[]
    by={(wf,s):[r for r in C if r['workflow']==wf and r['severity']==s] for wf in('manual','assist') for s in sevs}
    for _ in range(B):
        d=[]
        for k,v in by.items(): d+=random.choices(v,k=len(v))
        xs.append(stdz(d,key,w))
    xs.sort(); return xs[50],xs[1949]
for key in ['ttc','rm','ho']:
    print('std contrast',key,'pooled mix',round(stdz(C,key),2),boot(key))
    wa={s:sum(1 for r in rows if r['severity']==s and r['workflow']=='assist')/210 for s in sevs}
    wm={s:sum(1 for r in rows if r['severity']==s and r['workflow']=='manual')/210 for s in sevs}
    print('  at assist mix',round(stdz(C,key,wa),2),' at manual mix',round(stdz(C,key,wm),2))
# marginal decomposition of median/mean rm ttc
for key in ['ttc','rm']:
    ma=st.mean(r[key] for r in C if r['workflow']=='assist'); mm=st.mean(r[key] for r in C if r['workflow']=='manual'); print('marginal mean diff',key,round(ma-mm,2))
# per-severity diffs bootstrap (CI) for ttc,rm
for s in sevs:
    for key in ['ttc','rm']:
        a=[r[key] for r in C if r['workflow']=='assist' and r['severity']==s]; m=[r[key] for r in C if r['workflow']=='manual' and r['severity']==s]
        bs=sorted(st.mean(random.choices(a,k=len(a)))-st.mean(random.choices(m,k=len(m))) for _ in range(2000))
        print(s,key,round(st.mean(a)-st.mean(m),2),(round(bs[50],2),round(bs[1949],2)))
# missing sensitivity: sev1 assist, if missing 5 had ttc >= 7d(168h) 
tot={w:sum(r['rm'] for r in C if r['workflow']==w) for w in('manual','assist')}; print('recorded total rm',tot, 'hours',{k:v/60 for k,v in tot.items()})
# severity shift check against staffing interruptions
stf=rd('staffing.csv')
for w,rng in [('manual',range(1,8)),('assist',range(8,15))]:
    s=[x for x in stf if int(x['date'][-2:]) in rng]
    print(w,'resp',st.mean(int(x['active_responders']) for x in s),'sched hrs/day/grp',st.mean(int(x['scheduled_responder_hours']) for x in s),'interrupt min',st.mean(int(x['interruption_minutes']) for x in s))
